  color: rgba(255,255,255,0.85);
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--accent);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  background: var(--primary);
  padding: 1rem;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  color: white;
  padding: 0.75rem 0;
  text-decoration: none;
  font-weight: 500;
}

/* Banner */
.banner {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  padding: 0.75rem 2rem;
  text-align: center;
}

.banner p {
  color: white;
  font-size: 0.95rem;
}

.banner strong {
  color: var(--accent);
}

/* Featured Article */
.featured-section {
  max-width: 1200px;
  margin: 2rem auto;
  padding: 0 2rem;
}

.featured-card {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: var(--primary);
  min-height: 400px;
  display: flex;
  align-items: flex-end;
}

.featured-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.6;
}

.featured-content {
  position: relative;
  z-index: 1;
  padding: 2rem;
  color: white;
}

.featured-tag {
  display: inline-block;
  background: var(--tag-ai);
  color: white;
  padding: 0.3rem 0.75rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.featured-title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1rem;
  max-width: 600px;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.featured-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.9rem;
}

.featured-author {
  font-weight: 500;
}

.featured-time {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
}

/* Article Grid */
.article-section {
  max-width: 1200px;
  margin: 2rem auto;
  padding: 0 2rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}

.article-card:hover {
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
  transform: translateY(-2px);
}

.article-thumb {
  width: 100%;
  height: 160px;
  object-fit: cover;
  background: var(--bg-light);
}

.article-body {
  padding: 1rem;
}

.article-tag {
  display: inline-block;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.tag-ai { background: var(--tag-ai-bg); color: var(--tag-ai); }
.tag-web { background: var(--tag-web-bg); color: var(--tag-web); }
.tag-db { background: var(--tag-db-bg); color: var(--tag-db); }
.tag-elastic { background: var(--tag-elastic-bg); color: var(--tag-elastic); }
.tag-data { background: var(--tag-data-bg); color: var(--tag-data); }
.tag-python { background: var(--tag-elastic-bg); color: var(--tag-elastic); }
.tag-nodejs { background: var(--tag-db-bg); color: var(--tag-db); }
.tag-sheets { background: var(--tag-web-bg); color: var(--tag-web); }
.tag-auto { background: var(--tag-ai-bg); color: var(--tag-ai); }

.article-title {
