}

.article-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.article-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6rem;
  font-weight: 600;
  color: var(--primary);
}

.article-author {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.article-time {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-left: auto;
}

.load-more-container {
  text-align: center;
  margin-top: 2rem;
}

.load-more-btn {
  background: var(--primary);
  color: white;
  border: none;
  padding: 0.875rem 2rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.load-more-btn:hover {
  background: #1a1a4e;
}

/* Footer */
.site-footer {
  background: var(--bg-light);
  padding: 3rem 2rem;
  margin-top: 3rem;
  border-top: 1px solid var(--border);
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-mission {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  max-width: 700px;
}

.footer-section {
  margin-bottom: 1.5rem;
}

.footer-section h4 {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.75rem;
  color: var(--text-dark);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
}

.footer-links a {
  color: var(--link-blue);
