}

.footer-links-bottom {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.footer-links-bottom a {
  color: var(--text-muted);
}

/* Learn Page */
.learn-hero {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  padding: 3rem 2rem;
  text-align: center;
