/* OpenLearnHub Styles */
:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --link-blue: #002EAD;
  --bg-white: #FFFFFF;
  --bg-light: #F7F8FA;
  --text-dark: #1a1a2e;
  --text-muted: #6B7280;
  --border: #E5E7EB;
  --tag-ai: #3B82F6;
  --tag-ai-bg: #EFF6FF;
  --tag-web: #10B981;
  --tag-web-bg: #ECFDF5;
  --tag-db: #8B5CF6;
  --tag-db-bg: #F5F3FF;
  --tag-elastic: #F59E0B;
