  font-weight: 500;
  text-decoration: none;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--accent);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  background: var(--primary);
  padding: 1rem;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  color: white;
  padding: 0.75rem 0;
  text-decoration: none;
  font-weight: 500;
}

/* Banner */
.banner {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  padding: 0.75rem 2rem;
  text-align: center;
}

.banner p {
  color: white;
  font-size: 0.95rem;
}

.banner strong {
  color: var(--accent);
}

/* Featured Article */
.featured-section {
  max-width: 1200px;
  margin: 2rem auto;
  padding: 0 2rem;
}

.featured-card {
  position: relative;
  border-radius: 12px;
