  background: var(--primary);
  min-height: 400px;
  display: flex;
  align-items: flex-end;
}

.featured-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.6;
}

.featured-content {
  position: relative;
  z-index: 1;
  padding: 2rem;
  color: white;
}

.featured-tag {
  display: inline-block;
  background: var(--tag-ai);
  color: white;
  padding: 0.3rem 0.75rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.featured-title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1rem;
  max-width: 600px;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.featured-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.9rem;
}

.featured-author {
  font-weight: 500;
}

.featured-time {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
}

/* Article Grid */
.article-section {
  max-width: 1200px;
  margin: 2rem auto;
  padding: 0 2rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}

.article-card:hover {
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
  transform: translateY(-2px);
}

.article-thumb {
  width: 100%;
  height: 160px;
  object-fit: cover;
  background: var(--bg-light);
}

.article-body {
  padding: 1rem;
}

.article-tag {
  display: inline-block;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.tag-ai { background: var(--tag-ai-bg); color: var(--tag-ai); }
.tag-web { background: var(--tag-web-bg); color: var(--tag-web); }
.tag-db { background: var(--tag-db-bg); color: var(--tag-db); }
.tag-elastic { background: var(--tag-elastic-bg); color: var(--tag-elastic); }
.tag-data { background: var(--tag-data-bg); color: var(--tag-data); }
.tag-python { background: var(--tag-elastic-bg); color: var(--tag-elastic); }
.tag-nodejs { background: var(--tag-db-bg); color: var(--tag-db); }
.tag-sheets { background: var(--tag-web-bg); color: var(--tag-web); }
.tag-auto { background: var(--tag-ai-bg); color: var(--tag-ai); }

.article-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  line-height: 1.4;
  color: var(--text-dark);
}

.article-title a {
  color: inherit;
  text-decoration: none;
}

.article-title a:hover {
  color: var(--link-blue);
}

.article-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.article-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6rem;
  font-weight: 600;
  color: var(--primary);
}

.article-author {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.article-time {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-left: auto;
}

.load-more-container {
  text-align: center;
  margin-top: 2rem;
}

.load-more-btn {
  background: var(--primary);
  color: white;
  border: none;
  padding: 0.875rem 2rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.load-more-btn:hover {
  background: #1a1a4e;
}

/* Footer */
.site-footer {
  background: var(--bg-light);
  padding: 3rem 2rem;
  margin-top: 3rem;
  border-top: 1px solid var(--border);
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-mission {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  max-width: 700px;
}

.footer-section {
  margin-bottom: 1.5rem;
}

.footer-section h4 {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.75rem;
  color: var(--text-dark);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
}

.footer-links a {
  color: var(--link-blue);
  font-size: 0.9rem;
}

.footer-links-bottom {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.footer-links-bottom a {
  color: var(--text-muted);
}

/* Learn Page */
.learn-hero {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  padding: 3rem 2rem;
  text-align: center;
  color: white;
}

.learn-hero h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.learn-hero p {
  max-width: 600px;
  margin: 0 auto 1.5rem;
  opacity: 0.9;
}

.sign-in-btn {
  display: inline-block;
  background: var(--accent);
  color: var(--primary);
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
